import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"悯上","description":"","frontmatter":{"title":"悯上","date":"2026-11-24T00:00:00.000Z","seq":60,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王逸","source_book":"楚辞","prev":{"text":"疾世","link":"/blogs/楚辞/疾世.html"},"next":{"text":"遭厄","link":"/blogs/楚辞/遭厄.html"}},"headers":[],"relativePath":"blogs/楚辞/悯上.md","filePath":"blogs/楚辞/悯上.md"}'),o={name:"blogs/楚辞/悯上.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="悯上" tabindex="-1">悯上 <a class="header-anchor" href="#悯上" aria-label="Permalink to &quot;悯上&quot;">​</a></h1><p class="poem-meta">先秦 · 王逸　·　九思</p><div class="poem"><p class="poem-stanza">哀世兮睩睩，諓諓兮嗌喔。</p><p class="poem-stanza">众多兮阿媚，骪靡兮成俗。</p><p class="poem-stanza">贪枉兮党比，贞良兮茕独。</p><p class="poem-stanza">鹄窜兮枳棘，鹈集兮帷幄。</p><p class="poem-stanza">罽蕠兮青葱，槁本兮萎落。</p><p class="poem-stanza">睹斯兮伪惑，心为兮隔错。</p><p class="poem-stanza">逡巡兮圃薮，率彼兮畛陌。</p><p class="poem-stanza">川谷兮渊渊，山阜兮峉峉。</p><p class="poem-stanza">丛林兮崟崟，株榛兮岳岳。</p><p class="poem-stanza">霜雪兮漼溰，冰冻兮洛泽。</p><p class="poem-stanza">东西兮南北，罔所兮归薄。</p><p class="poem-stanza">庇廕兮枯树，匍匐兮岩石。</p><p class="poem-stanza">蜷跼兮寒局数，独处兮志不申。</p><p class="poem-stanza">年齿尽兮命迫促，魁垒挤摧兮常困辱。</p><p class="poem-stanza">含忧强老兮愁无乐，须发苎悴兮顠鬓白。</p><p class="poem-stanza">思灵泽兮一膏沐，怀兰英兮把琼若，待天明兮立踯躅。</p><p class="poem-stanza">云蒙蒙兮电鯈烁，孤雌惊兮鸣呴呴。</p><p class="poem-stanza">思怫郁兮肝切剥，忿悁悒兮孰诉告。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
